const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const { cc, load, project, ts } = require('../cocos-test/v3-loader.cjs');
const { spawnSync } = require('node:child_process');
const { regionCameraBounds, focusedViewportSize } = load(project + '/src/core/RegionCamera.ts');
const { GameSession } = load(project + '/src/core/GameSession.ts');
const { OnsenGame } = load(project + '/src/adapters/cocos/OnsenGame.ts');
const geometry = load(project + '/src/adapters/cocos/OnsenGeometry.ts');
const bytes = fs.readFileSync(project + '/data/onsen-layout.json');
const layout = JSON.parse(bytes);
const clone = value => structuredClone(value);
const hash = value => crypto.createHash('sha256').update(value).digest('hex');
const sourceSerialization = JSON.stringify(layout);
const checks = [], samples = [];
const check = (name, callback) => { callback(); checks.push({ name, passed: true }); };
const round = value => Math.round(value * 10000) / 10000;
const inside = (rect, owner) => {
  for (const local of [{ x: 0, y: 0 }, { x: owner.sourceSize.width, y: 0 },
    { x: 0, y: owner.sourceSize.height }, { x: owner.sourceSize.width, y: owner.sourceSize.height }]) {
    const point = geometry.transformedPoint(owner, local);
    assert.ok(point.x >= rect.x - 1e-5 && point.x <= rect.x + rect.width + 1e-5, `${owner.stickerId} X`);
    assert.ok(point.y >= rect.y - 1e-5 && point.y <= rect.y + rect.height + 1e-5, `${owner.stickerId} Y`);
  }
};
const requiredOwners = target => {
  const found = new Map();
  const add = owner => { if (found.has(owner.stickerId)) return; found.set(owner.stickerId, owner);
    for (const id of owner.dependsOn || []) add(layout.stickers.find(candidate => candidate.stickerId === id)); };
  add(target); return [...found.values()];
};

check('Cocos 3.8.8 official declarations compile all camera and responsive layout source strictly', () => {
  const output = spawnSync(process.execPath, [path.join(path.dirname(ts.sys.getExecutingFilePath()), 'tsc.js'), '-p',
    path.resolve(__dirname, '../cocos-test/tsconfig.json')], { encoding: 'utf8' });
  assert.equal(output.status, 0, output.stdout + output.stderr);
});
check('All seven regional views remain visibly magnified in portrait, desktop and short landscape boards', () => {
  for (const block of layout.geoBlocks) {
    const focus = regionCameraBounds(layout, layout, block.blockId);
    assert.equal(focus.mode, block.blockId === 'garden' ? 'local' : 'region');
    for (const available of [{ width: 358, height: 509 }, { width: 328, height: 405 },
      { width: 760, height: 553 }, { width: 528, height: 430 }, { width: 760, height: 240 }]) {
      const viewport = focusedViewportSize(available, focus.bounds);
      assert.ok(viewport.width <= available.width + 1e-6 && viewport.height <= available.height + 1e-6);
      assert.ok(Math.abs(viewport.width / viewport.height - focus.bounds.width / focus.bounds.height) < 1e-7);
      const camera = geometry.fitCamera(focus.bounds, viewport, 0);
      const zoomRelativeToOverviewWidth = layout.scene.width * camera.scale / viewport.width;
      assert.ok(zoomRelativeToOverviewWidth > 2.5, `${block.blockId} was fitted to a whole-scene width`);
      const targets = focus.mode === 'region' ? layout.stickers.filter(owner => owner.geoBlock === block.blockId)
        : requiredOwners(layout.stickers.find(owner => owner.stickerId === focus.focusStickerId));
      for (const owner of targets) inside(focus.bounds, owner);
      samples.push({ blockId: block.blockId, mode: focus.mode, available, viewport,
        bounds: focus.bounds, relativeWidthZoom: round(zoomRelativeToOverviewWidth) });
    }
  }
});
check('The entire wide garden follows each of its nine current target locations instead of shrinking to full scene', () => {
  for (const owner of layout.stickers.filter(owner => owner.geoBlock === 'garden')) {
    const focus = regionCameraBounds(layout, layout, 'garden', { focusStickerId: owner.stickerId });
    assert.equal(focus.focusStickerId, owner.stickerId); assert.equal(focus.mode, 'local');
    assert.ok(focus.bounds.width < layout.scene.width * 0.45);
    for (const support of requiredOwners(owner)) inside(focus.bounds, support);
  }
});
check('All 161 objects can have a local detail view with their full transformed artwork and every real supporting ancestor', () => {
  for (const owner of layout.stickers) {
    const focus = regionCameraBounds(layout, layout, owner.geoBlock, { focusStickerId: owner.stickerId, detailFocus: true });
    assert.equal(focus.mode, 'local'); assert.equal(focus.focusStickerId, owner.stickerId);
    assert.ok(focus.bounds.width >= 300 && focus.bounds.height >= 220);
    for (const support of requiredOwners(owner)) inside(focus.bounds, support);
  }
});
check('A moved, anchored, scaled and rotated object beyond a scene edge stays reachable without forcing every remote object into its camera', () => {
  for (const position of [{ x: -210, y: 300 }, { x: 2300, y: 200 }, { x: 1000, y: -400 }]) {
    const edited = clone(layout), target = edited.stickers.find(owner => owner.stickerId === 'L006');
    Object.assign(target, { position, scale: 1.7, rotation: 67, anchor: { x: 0.35, y: 0.72 } });
    const focus = regionCameraBounds(edited, layout, target.geoBlock, { focusStickerId: target.stickerId });
    assert.equal(focus.mode, 'local'); assert.equal(focus.focusStickerId, target.stickerId);
    inside(focus.bounds, target); assert.ok(focus.bounds.width <= 640.001);
    if (position.y < 0) assert.equal(focus.keepInScene.y, false); else assert.equal(focus.keepInScene.x, false);
  }
});

// Execute the actual controller's relayout and drawTray against a bounded node
// host. This verifies node geometry and touch-handler attachment, not engine/GPU.
cc.Node.prototype.on = function (type, callback) { (this.events ||= []).push({ type, callback }); };
cc.Node.EventType = { TOUCH_START: 'touch-start' };
check('Actual Cocos relayout uses a right 2x2 tray in short landscape and a bottom tray in portrait, with non-overlapping card rectangles', () => {
  for (const block of layout.geoBlocks) for (const size of [{ width: 390, height: 844 }, { width: 360, height: 740 },
    { width: 1440, height: 900 }, { width: 756, height: 558 }, { width: 1024, height: 600 }]) {
    const game = new OnsenGame();
    game.layout = layout; game.sourceLayout = layout; game.draft = clone(layout); game.session = new GameSession(layout);
    let fixturePlacements = 0;
    while (game.session.getSnapshot().activeBlockId !== block.blockId) {
      const state = game.session.getSnapshot();
      if (state.phase === 'transitioning') { game.session.finishTransition(); continue; }
      const id = state.availableStickerIds[0]; assert.ok(id);
      assert.equal(game.session.select(id), true);
      assert.equal(game.session.commitPlacement(game.session.beginPlacement(id)), true); fixturePlacements++;
    }
    game.booted = true; game.alive = true; game.clearPaper = () => {}; game.clearGhost = () => {};
    const node = (parent, name, width, height) => { const child = new cc.Node(name); const transform = child.addComponent(cc.UITransform);
      transform.setContentSize(width, height); if (parent) parent.addChild(child); return child; };
    game.ui = node(null, 'UI', size.width, size.height);
    game.makeNode = node; game.makePanel = node;
    game.makeLabel = (parent, text, _font, width, height, x = 0, y = 0) => {
      const child = node(parent, 'label', width, height); child.setPosition(x, y); return { node: child, string: text };
    };
    game.makeButton = (parent, id, _label, width, height, x, y) => { const child = node(parent, id, width, height);
      child.setPosition(x, y); game.buttons.set(id, { interactable: true }); return child; };
    game.sprite = (parent, _frame, sourceSize, name) => node(parent, name, sourceSize.width, sourceSize.height);
    game.paintWorld = () => {}; game.updateStatus = () => {};
    for (const owner of layout.stickers) game.frames.set(owner.file, {});
    game.relayout();
    const shouldBeSide = size.width >= 700 && size.height < 700;
    assert.equal(game.sideTray, shouldBeSide);
    const board = game.board.position, tray = game.tray.position, traySize = game.tray.getComponent(cc.UITransform);
    if (shouldBeSide) assert.ok(board.x + game.boardSize.width / 2 < tray.x - traySize.width / 2);
    else assert.ok(board.y - game.boardSize.height / 2 > tray.y + traySize.height / 2);
    const panel = game.tray.getChildByName('CardsAndControls');
    const cards = panel.children.filter(child => child.name.startsWith('PaperCard:'));
    assert.ok(cards.length >= 1 && cards.length <= 4);
    for (let a = 0; a < cards.length; a++) for (let b = a + 1; b < cards.length; b++) {
      const left = cards[a], right = cards[b], ls = left.getComponent(cc.UITransform), rs = right.getComponent(cc.UITransform);
      assert.ok(Math.abs(left.position.x - right.position.x) >= (ls.width + rs.width) / 2
        || Math.abs(left.position.y - right.position.y) >= (ls.height + rs.height) / 2);
    }
    const camera = game.cameraForBlock(block.blockId);
    const relativeWidthZoom = layout.scene.width * camera.scale / game.boardSize.width;
    assert.ok(relativeWidthZoom > 2.35);
    samples.push({ actualCocosController: true, blockId: block.blockId, fixturePlacements, viewport: size, sideTray: game.sideTray,
      boardSize: game.boardSize, cards: cards.length, relativeWidthZoom: round(relativeWidthZoom) });
  }
});
check('Region camera math leaves original PNG transforms, global layering and all layout bytes unchanged', () => {
