export interface RegionRect { x: number; y: number; width: number; height: number }
export interface RegionFocus {
  bounds: RegionRect;
  keepInScene: { x: boolean; y: boolean };
  mode: 'region' | 'local' | 'overview';
  focusStickerId: string | null;
}
export interface RegionFocusOptions {
  focusStickerId?: string | null;
  availableStickerIds?: readonly string[];
}
type Point = { x: number; y: number };
type Pose = { position: Point; sourceSize: { width: number; height: number }; anchor: Point; scale: number; rotation: number };

const point = (owner: Pose, local: Point): Point => {
  const angle = owner.rotation * Math.PI / 180;
  const x = (local.x - owner.anchor.x * owner.sourceSize.width) * owner.scale;
  const y = (local.y - owner.anchor.y * owner.sourceSize.height) * owner.scale;
  return { x: owner.position.x + x * Math.cos(angle) - y * Math.sin(angle),
    y: owner.position.y + x * Math.sin(angle) + y * Math.cos(angle) };
};
const rectForPoints = (points: Point[]): RegionRect => {
  const xs = points.map(p => p.x), ys = points.map(p => p.y);
  const x = Math.min(...xs), y = Math.min(...ys);
  return { x, y, width: Math.max(...xs) - x, height: Math.max(...ys) - y };
};
const corners = (owner: Pose, offset: Point, size: { width: number; height: number }): Point[] =>
  [{ x: 0, y: 0 }, { x: size.width, y: 0 }, { x: 0, y: size.height }, { x: size.width, y: size.height }]
    .map(corner => point(owner, { x: offset.x + corner.x, y: offset.y + corner.y }));
const union = (rects: RegionRect[], padding = 0): RegionRect => {
  const x = Math.min(...rects.map(r => r.x)), y = Math.min(...rects.map(r => r.y));
  const right = Math.max(...rects.map(r => r.x + r.width)), bottom = Math.max(...rects.map(r => r.y + r.height));
  return { x: x - padding, y: y - padding, width: right - x + padding * 2, height: bottom - y + padding * 2 };
};

/**
 * A regional camera is based on rendered world geometry, never native PNG pixels.
 * Normal rooms keep their complete objects together. A scene-wide region (the
 * garden), or a far-away editor move, follows the held/next object and its real
 * supports so that fitting every distant object cannot silently undo the zoom.
 */
export function regionCameraBounds(layout: GameLayout, sourceLayout: GameLayout,
  blockId: string | null, options: RegionFocusOptions = {}): RegionFocus {
  const scene = layout.scene as { width: number; height: number };
  const overview = (): RegionFocus => ({ bounds: { x: 0, y: 0, width: scene.width, height: scene.height },
    keepInScene: { x: true, y: true }, mode: 'overview', focusStickerId: null });
  const block = layout.geoBlocks.find(candidate => candidate.blockId === blockId);
  if (!block) return overview();
  const owners = layout.stickers.filter(owner => owner.geoBlock === blockId);
  if (!owners.length) return overview();
  const renderParts = assemblyRenderParts(layout, sourceLayout);
  const ownerBounds = new Map<string, RegionRect>();
  for (const owner of layout.stickers) {
    const parts = renderParts.get(owner.stickerId) ?? [];
    const points = parts.length ? parts.flatMap(part => corners(owner, part.offset,
      (part.sourceSize as { width: number; height: number } | undefined) ?? owner.sourceSize))
      : corners(owner, { x: 0, y: 0 }, owner.sourceSize);
    ownerBounds.set(owner.stickerId, rectForPoints(points));
  }
  const attachmentBounds = (ids: ReadonlySet<string>): RegionRect[] => {
    const result: RegionRect[] = [];
    for (const value of layout.fixedLayers ?? []) {
      const fixed = value as unknown as Pose & { attachment?: { stickerId: string; offset: Point; inheritTransform?: boolean } };
      const attachment = fixed.attachment;
      if (!attachment || !ids.has(attachment.stickerId)) continue;
      const support = layout.stickers.find(owner => owner.stickerId === attachment.stickerId);
      if (!support) continue;
      const pose = attachment.inheritTransform === false ? fixed : { ...fixed,
        position: point(support, attachment.offset), scale: fixed.scale * support.scale,
        rotation: fixed.rotation + support.rotation };
      result.push(rectForPoints(corners(pose, { x: 0, y: 0 }, fixed.sourceSize)));
    }
    return result;
  };
  const padding = typeof block.cameraPadding === 'number' ? block.cameraPadding : 24;
  const originalRegion = (block.cameraBounds ?? block.bounds) as RegionRect;
  const regionalIds = new Set(owners.map(owner => owner.stickerId));
  const actualRegional = [...owners.map(owner => ownerBounds.get(owner.stickerId)!), ...attachmentBounds(regionalIds)];
  const regional = union([originalRegion, union(actualRegional, padding)]);
  const inside = (rects: RegionRect[]): { x: boolean; y: boolean } => ({
    x: rects.every(r => r.x >= 0 && r.x + r.width <= scene.width),
    y: rects.every(r => r.y >= 0 && r.y + r.height <= scene.height),
  });
  if (regional.width <= scene.width * 0.62 && regional.height <= scene.height * 0.8) {
    return { bounds: regional, keepInScene: inside(actualRegional), mode: 'region', focusStickerId: null };
  }

  const focus = owners.find(owner => owner.stickerId === options.focusStickerId)
    ?? options.availableStickerIds?.map(id => owners.find(owner => owner.stickerId === id)).find(Boolean)
    ?? (block.assemblyOrder as string[] | undefined)?.map(id => owners.find(owner => owner.stickerId === id)).find(Boolean)
    ?? owners[0];
  const required = new Set<string>();
  const addSupports = (owner: StickerPlacement): void => {
    if (required.has(owner.stickerId)) return;
    required.add(owner.stickerId);
    for (const id of owner.dependsOn ?? []) {
      const support = layout.stickers.find(candidate => candidate.stickerId === id);
      if (support) addSupports(support);
    }
  };
  addSupports(focus);
  const actualLocal = [...[...required].map(id => ownerBounds.get(id)!), ...attachmentBounds(required)];
  const content = union(actualLocal, padding);
  const width = Math.max(640, content.width), height = Math.max(430, content.height);
  return { bounds: { x: content.x + content.width / 2 - width / 2,
    y: content.y + content.height / 2 - height / 2, width, height },
    keepInScene: inside(actualLocal), mode: 'local', focusStickerId: focus.stickerId };
}

/** Fit the board's shape too; a wide, short board otherwise reveals the whole scene. */
export function focusedViewportSize(available: { width: number; height: number },
  bounds: RegionRect): { width: number; height: number } {
  const aspect = bounds.width / bounds.height;
  const width = Math.min(available.width, available.height * aspect);
  return { width, height: width / aspect };
}

