  private async runTour(): Promise<void> {
    if (this.session.getSnapshot().phase !== 'transitioning') return;
    this.busy = true; this.updateStatus(); this.clearPaper();
    const current = this.session.getSnapshot().activeBlockId;
    const blocks = [...this.layout.geoBlocks].sort((a, b) => a.blockOrder - b.blockOrder);
    const next = blocks[blocks.findIndex(block => block.blockId === current) + 1];
    if (!await this.moveCamera(this.cameraForScene(), 0.7)) return;
    if (!await this.animate(0.45, () => undefined)) return;
    if (next && !await this.moveCamera(this.cameraForBlock(next.blockId), 0.8)) return;
    this.overview = !next;
    this.session.finishTransition(); this.busy = false; this.refresh();
  }
  private setCamera(camera: CameraPose): void {
    this.camera = { ...camera };
    if (this.world && isValid(this.world)) { this.world.setPosition(camera.x, camera.y); this.world.setScale(camera.scale, camera.scale, 1); }
  }
  private cameraForScene(): CameraPose { const scene = this.scene(); return fitCamera({ x: 0, y: 0, width: scene.width, height: scene.height }, this.boardSize, 12 * this.unit); }
  private cameraForBlock(id: string | null): CameraPose {
    const bounds = this.block(id)?.cameraBounds as Bounds | undefined;
    if (!bounds) return this.cameraForScene();
    // Include each complete transformed object, including edits beyond source bounds.
    const layout = this.liveLayout();
    const supports = layout.stickers.filter(sticker => sticker.geoBlock === id);
    const attachments = this.fixed(layout).filter(fixed => fixed.attachment?.inheritTransform
      && supports.some(owner => owner.stickerId === fixed.attachment!.stickerId))
      .map(fixed => fixedWorldTransform(fixed, layout.stickers));
    const boundsWithEdits = cameraContentBounds(bounds, [...supports, ...attachments]);
    return clampCameraToScene(fitCamera(boundsWithEdits, this.boardSize, 12 * this.unit), boundsWithEdits, this.boardSize, this.scene());
  }
  private async moveCamera(target: CameraPose, seconds: number): Promise<boolean> {
    const from = { ...this.camera };
    return this.animate(seconds, progress => { const t = smooth(progress); this.setCamera({ x: lerp(from.x, target.x, t), y: lerp(from.y, target.y, t), scale: lerp(from.scale, target.scale, t) }); });
  }
  private animate(duration: number, step: (progress: number) => void): Promise<boolean> {
    if (!this.alive || !this.enabled) return Promise.resolve(false);
    return new Promise(resolve => { const motion: Motion = { duration, elapsed: 0, step, finish: resolve }; this.motions.add(motion); step(0); });
  }
  private cancelMotions(): void { for (const motion of this.motions) motion.finish(false); this.motions.clear(); }

  private undo(): void {
    if (this.busy || this.editing) return;
    if (this.session.undo()) { this.overview = false; this.clearPaper(); this.setCamera(this.cameraForBlock(this.session.getSnapshot().activeBlockId)); this.refresh(); }
  }
