export interface PlacementTargetOptions {
  /** Complete PNG canvas dimensions in unscaled source-local world units. */
  width: number;
  height: number;
  /** Uniform owner scale multiplied by the active camera's display scale. */
  worldToScreenScale: number;
  /** Candidate point after the owner's inverse rotation, anchor and scale. */
  localPoint: { x: number; y: number };
  /** Exact canonical alpha >= 19 test; no transparent-bounds fallback. */
  alphaHitLocal(x: number, y: number): boolean;
  /** Cocos UI density unit; ordinary Canvas screen coordinates use 1. */
  screenToleranceScale?: number;
}

/** Selected-target drop assist only. Editing/picking must keep exact alpha hits.
 * Screen-space limits stay bounded at every camera zoom. The small central
 * circle lets a hollow rack/chair land at its natural center; transparent
 * regions elsewhere only accept near the actual painted object.
 */
export function dropTargetAccepts(options: PlacementTargetOptions): boolean {
  const { width, height, worldToScreenScale: scale, localPoint: point, alphaHitLocal } = options;
  const density = options.screenToleranceScale ?? 1;
  if (![width, height, scale, point.x, point.y, density].every(Number.isFinite)
    || width <= 0 || height <= 0 || scale <= 0 || density <= 0) return false;
  const inSource = (x: number, y: number): boolean => x >= 0 && y >= 0 && x < width && y < height;
  if (inSource(point.x, point.y) && alphaHitLocal(point.x, point.y)) return true;
  const centerRadius = Math.max(22 * density, Math.min(32 * density, Math.min(width, height) * scale * .24));
  if (Math.hypot(point.x - width / 2, point.y - height / 2) * scale <= centerRadius) return true;
  const radius = 22 * density;
  const localRadius = radius / scale;
  if (point.x < -localRadius || point.y < -localRadius
    || point.x > width + localRadius || point.y > height + localRadius) return false;
  // Sample in display units, not a source-pixel radius capped at low zoom.
  // At most 1,516 neighbor checks on release; thin outlines remain hittable.
  const step = density;
  for (let sy = -22; sy <= 22; sy++) for (let sx = -22; sx <= 22; sx++) {
    if (sx * sx + sy * sy > 22 * 22 || (sx === 0 && sy === 0)) continue;
    const x = point.x + sx * step / scale, y = point.y + sy * step / scale;
    if (inSource(x, y) && alphaHitLocal(x, y)) return true;
  }
  return false;
}

import { AreaLevel, GameLayout, GameSession, LayoutRevision, refreshPlayMetadata, SessionSave } from './GameSession';
import { validateRenderableLayout } from './RenderableLayout';

export interface EditedAssemblyUpgrade {
  layout: GameLayout;
  previousLayout: GameLayout;
  previousLayoutRevision: LayoutRevision;
}

const clone = <T>(value: T): T => JSON.parse(JSON.stringify(value)) as T;
const levels: AreaLevel[] = ['L1', 'L2', 'L3'];

/**
 * Pure, explicitly scoped upgrade of a previously accepted edited layout.
 * Preserve the user's world transforms, ownership, fixed geometry and exact
 * painter queue. Merge only current gameplay roles and area metadata. The
 * caller archives the old layout and keeps its progress key before persisting
 * the returned revision, which cannot collide with the default source revision.
 */
export function upgradeEditedAssemblyLayout(source: GameLayout, edited: unknown): EditedAssemblyUpgrade | null {
  if (!source.assemblyPolicy || typeof source.layoutRevision !== 'number'
    || validateRenderableLayout(edited, source).length) return null;
  const previous = edited as GameLayout;
  if (previous.assemblyPolicy?.version === source.assemblyPolicy.version
    && previous.assemblyPolicy?.readyPolicy === source.assemblyPolicy.readyPolicy) return null;
  if (typeof previous.layoutRevision !== 'number' || !Number.isSafeInteger(previous.layoutRevision + 1)) return null;
  const upgraded = clone(previous);
  if (!Number.isSafeInteger(source.layoutRevision + 1)) return null;
  upgraded.layoutRevision = Math.max(source.layoutRevision + 1, previous.layoutRevision + 1);
  upgraded.sourceLayoutRevision = source.layoutRevision;
  upgraded.assemblyPolicy = clone(source.assemblyPolicy);
  const sourceByID = new Map(source.stickers.map(sticker => [sticker.stickerId, sticker]));
  const legacyAreaLevels: Record<string, AreaLevel> = {};
  for (const sticker of upgraded.stickers) {
    const role = sourceByID.get(sticker.stickerId)!;
    legacyAreaLevels[sticker.stickerId] = sticker.areaLevel;
    sticker.areaLevel = role.areaLevel;
    sticker.areaLevelBasis = role.areaLevelBasis;
    sticker.effectiveAlphaArea = role.effectiveAlphaArea;
    // Keep all user transforms and painter order, but actual support claims
    // must follow the current verified complete artwork's support structures.
    sticker.dependsOn = clone(role.dependsOn ?? []);
  }
  const byID = new Map(upgraded.stickers.map(sticker => [sticker.stickerId, sticker]));
  let changed = true;
  while (changed) {
    changed = false;
    for (const sticker of upgraded.stickers) for (const dependency of sticker.dependsOn ?? []) {
      const support = byID.get(dependency)!;
      if (support.geoBlock === sticker.geoBlock && levels.indexOf(support.areaLevel) > levels.indexOf(sticker.areaLevel)) {
        support.areaLevel = sticker.areaLevel; changed = true;
      }
    }
  }
  upgraded.progressMigration = {
    fromLayoutRevisions: [previous.layoutRevision], targetLayoutRevision: upgraded.layoutRevision,
    legacyAreaLevels,
    rule: 'Explicit edited-layout assembly upgrade: retain original chronological placed IDs, validate historical edited stages and current supports, and use current stages only for remaining objects; old storage keys remain untouched',
  };
  upgraded.editedAssemblyUpgrade = {
    fromLayoutRevision: previous.layoutRevision, sourceLayoutRevision: source.layoutRevision,
    toLayoutRevision: upgraded.layoutRevision, policyVersion: source.assemblyPolicy.version,
    preserved: 'user transforms, block ownership, exact painter queue and original progress chronology',
  };
  const errors = validateRenderableLayout(upgraded, source);
  if (errors.length) throw new Error(`Edited assembly upgrade is incompatible: ${errors.join('; ')}`);
  refreshPlayMetadata(upgraded);
  return { layout: upgraded, previousLayout: clone(previous), previousLayoutRevision: previous.layoutRevision };
}

/** Validate before either new layout or progress is committed to storage. */
export function migrateEditedAssemblyProgress(upgrade: EditedAssemblyUpgrade, historical: unknown): SessionSave | null {
  try {
    const original = new GameSession(upgrade.previousLayout);
    if (!original.restore(historical).ok) return null;
    const candidate = clone(original.exportSave());
    candidate.layoutRevision = upgrade.layout.layoutRevision;
    if (candidate.placedStickerIds.length) candidate.legacyAssemblyPrefix = {
      sourceLayoutRevision: upgrade.previousLayoutRevision, count: candidate.placedStickerIds.length,
    };
    const updated = new GameSession(upgrade.layout);
    return updated.restore(candidate).ok ? updated.exportSave() : null;
  } catch { return null; }
}

import { GameLayout, GameSession, LayoutRevision, SessionSave } from './GameSession';

/** Explicit source upgrade; user-edited layouts keep their own progress. */
export function compatibleProgressRevisions(source: GameLayout, live: GameLayout,
  acceptedEditedLayout = false): LayoutRevision[] {
  if (acceptedEditedLayout || source.layoutRevision !== live.layoutRevision
    || typeof source.layoutRevision !== 'number' || source.sceneId !== live.sceneId) return [];
  const policy = source.progressMigration as { fromLayoutRevisions?: unknown; targetLayoutRevision?: unknown } | undefined;
  if (!policy || (policy.targetLayoutRevision !== undefined && policy.targetLayoutRevision !== source.layoutRevision)
    || !Array.isArray(policy.fromLayoutRevisions)) return [];
  const revisions = policy.fromLayoutRevisions;
  return [3, 2, 1].filter(revision => revision < (source.layoutRevision as number) && revisions.includes(revision));
}

/** Pure validation: neither source layout nor historical save is changed or written. */
export function migrateCompatibleProgress(source: GameLayout, live: GameLayout,
  historical: unknown, acceptedEditedLayout = false): SessionSave | null {
  if (!historical || typeof historical !== 'object' || Array.isArray(historical)) return null;
  const previous = historical as Partial<SessionSave>;
  if (!compatibleProgressRevisions(source, live, acceptedEditedLayout).includes(previous.layoutRevision!)
    || previous.sceneId !== live.sceneId) return null;
  try {
    const candidate = JSON.parse(JSON.stringify(previous)); candidate.layoutRevision = live.layoutRevision;
    const policy = source.progressMigration as { legacyAreaLevels?: unknown } | undefined;
    if (source.assemblyPolicy && policy?.legacyAreaLevels && Array.isArray(candidate.placedStickerIds)
      && candidate.placedStickerIds.length) {
      // Restore validates the old stage chronology against the declared source
      // levels and current support dependencies. New play obeys the new stages;
      // no object is silently added, deleted or reordered by this upgrade.
      candidate.legacyAssemblyPrefix = {
        sourceLayoutRevision: previous.layoutRevision, count: candidate.placedStickerIds.length,
      };
    }
    const validation = new GameSession(live);
    return validation.restore(candidate).ok ? validation.exportSave() : null;
  } catch { return null; }
}

