 const browser=await chromium.launch({executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',headless:true});
 try{
  const context=await browser.newContext({viewport:{width:390,height:844},deviceScaleFactor:2,hasTouch:true,isMobile:true});
  await context.addInitScript(save=>localStorage.setItem(`onsen-preview:onsen:progress:${save.sceneId}:${save.layoutRevision}`,JSON.stringify(save)),fixture);
  const page=await context.newPage(),errors=[];
  page.on('pageerror',e=>errors.push(e.message));
  await page.goto('file://'+path.join(root,'outputs/月下温泉-交互验证.html'));
  await page.waitForFunction(()=>window.onsenGame?.getViewState().loaded);
  assert.equal(await page.evaluate(()=>window.onsenGame.session.getSnapshot().progress.placed),total-1);
  await page.evaluate(()=>{
   const source=document.getElementById('game'),canvas=document.createElement('canvas');canvas.width=390;canvas.height=844;
   const c=canvas.getContext('2d'),stream=canvas.captureStream(30),chunks=[];
   const mimeType=MediaRecorder.isTypeSupported('video/webm;codecs=vp8')?'video/webm;codecs=vp8':'video/webm';
   const recorder=new MediaRecorder(stream,{mimeType,videoBitsPerSecond:2500000});
   const capture={recorder,stream,stopped:false,frame:null,result:null};
   capture.result=new Promise(resolve=>{
    recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};
    recorder.onstop=async()=>{const bytes=new Uint8Array(await new Blob(chunks,{type:mimeType}).arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=32768)binary+=String.fromCharCode(...bytes.subarray(i,i+32768));resolve({base64:btoa(binary),bytes:bytes.length,mimeType})};
   });
   const draw=()=>{if(capture.stopped)return;c.drawImage(source,0,0,390,844);capture.frame=requestAnimationFrame(draw)};
   draw();recorder.start(100);window.onsenCapture=capture;
  });
  const started=Date.now();await pause(800);
  const tray=await page.evaluate(id=>{const h=window.onsenGame.hits.find(h=>h.id==='sticker:'+id);return{x:h.x+h.width/2,y:h.y+h.height/2}},finalId);
  await page.touchscreen.tap(tray.x,tray.y);await pause(900);
  await page.screenshot({path:path.join(out,'held.png')});
  const target=await page.evaluate(id=>{
   const g=window.onsenGame,s=g.sticker(id),a=g.alpha(s);let best=Infinity,px=0,py=0;
   for(let y=0;y<a.height;y++)for(let x=0;x<a.width;x++)if(a.pixels[(y*a.width+x)*4+3]>220){const d=(x-a.width/2)**2+(y-a.height/2)**2;if(d<best){best=d;px=x+.5;py=y+.5}}
   const angle=s.rotation*Math.PI/180;
   const dx=(px*s.sourceSize.width/a.width-s.anchor.x*s.sourceSize.width)*s.scale;
   const dy=(py*s.sourceSize.height/a.height-s.anchor.y*s.sourceSize.height)*s.scale;
   return g.screen({x:s.position.x+dx*Math.cos(angle)-dy*Math.sin(angle),y:s.position.y+dx*Math.sin(angle)+dy*Math.cos(angle)});
  },finalId);
  await page.touchscreen.tap(target.x,target.y);
  await page.waitForFunction(count=>window.onsenGame.session.getSnapshot().progress.placed===count,total);
  await pause(400);await page.screenshot({path:path.join(out,'region-stars.png')});
  await page.waitForFunction(first=>window.onsenGame.session.getSnapshot().activeBlockId!==first&&!window.onsenGame.getViewState().tour,block.blockId);
  await page.screenshot({path:path.join(out,'next-region.png')});
  await pause(Math.max(0,11000-(Date.now()-started)));
  const data=await page.evaluate(async()=>{const c=window.onsenCapture;c.stopped=true;cancelAnimationFrame(c.frame);c.recorder.stop();const d=await c.result;c.stream.getTracks().forEach(t=>t.stop());return d});
  fs.writeFileSync(path.join(out,'region-demo.webm'),Buffer.from(data.base64,'base64'));assert.equal(errors.length,0);assert.ok(data.bytes>50000);
  const report={passed:true,scope:'browser diagnostic Canvas footage',presetCompletedIds:fixture.placedStickerIds,realTouchStickerId:finalId,firstBlock: block.blockId,regionCompleted:true,durationMs:Date.now()-started,bytes:data.bytes,errors};
  fs.writeFileSync(path.join(out,'report.json'),JSON.stringify(report,null,2));console.log(JSON.stringify({passed:true,realTouchStickerId:finalId,durationMs:report.durationMs,bytes:data.bytes}));
  await context.close();
 }finally{await browser.close()}
})().catch(e=>{console.error(e);process.exitCode=1});

